{"tool":"write","path":"tests/test_export.py","content":""""Additional tests for reports.export.export_csv."""
import unittest

from reports import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(
            export_csv([{"name": "Ada", "score": 3}], ["name", "score"]),
            "name,score\r\nAda,3\r\n",
        )

    def test_header_only_when_no_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}, {"a": 2}], []), "\r\n\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_quoting(self):
        self.assertEqual(
            export_csv([{"x": 'say "hi"', "y": "a,b", "z": "p\r\nq"}],
                       ["x", "y", "z"]),
            'x,y,z\r\n"say ""hi""","a,b","p\r\nq"\r\n',
        )

    def test_missing_and_none_become_empty(self):
        self.assertEqual(
            export_csv([{"a": None}, {"b": 5}, {}], ["a", "b"]),
            "a,b\r\n,\r\n,5\r\n,\r\n",
        )

    def test_non_string_values_use_str(self):
        self.assertEqual(
            export_csv([{"a": 1.5, "b": True, "c": (1, 2)}], ["a", "b", "c"]),
            "a,b,c\r\n1.5,True,(1, 2)\r\n",
        )

    def test_unselected_fields_ignored(self):
        self.assertEqual(
            export_csv([{"a": 1, "b": 2}], ["a"]),
            "a\r\n1\r\n",
        )

    def test_one_shot_generators(self):
        rows = ({"a": i} for i in range(3))
        cols = (c for c in ["a"])
        self.assertEqual(export_csv(rows, cols), "a\r\n0\r\n1\r\n2\r\n")

    def test_unicode_preserved(self):
        self.assertEqual(
            export_csv([{"a": "caf\u00e9 \u4e2d\u6587"}], ["a"]),
            "a\r\ncaf\u00e9 \u4e2d\u6587\r\n",
        )

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"a": 1}], ["a", "a"])

    def test_non_string_columns_rejected(self):
        for bad in [1, None, b"a"]:
            with self.assertRaises(ValueError):
                export_csv([{"a": 1}], ["a", bad])

    def test_column_validation_happens_before_consuming_rows(self):
        def explode():
            raise AssertionError("rows should not be consumed")
            yield {}
        with self.assertRaises(ValueError):
            export_csv(explode(), ["a", "a"])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()
